1	//! Cloud sync enforcement layer (M017/S01 + S02).
2	//!
3	//! [`CloudEnforcer`] bridges the file interception event loop and cloud sync
4	//! folder detection to enforce DLP policies on files stored in sync client
5	//! folders (OneDrive, Google Drive, Dropbox, Box).
6	//!
7	//! ## Decision logic
8	//!
9	//! 1. Check if the file path is inside a known sync folder.
10	//! 2. If the action is a write/create/move that targets a T3/T4 file inside a
11	//!    sync folder, return a [`CloudBlockResult`] with `Decision::DENY`.
12	//! 3. Otherwise return `None` (fall through to ABAC).
13	//!
14	//! ## Sync folder detection (S02)
15	//!
16	//! [`resolve_sync_paths`] reads the actual sync-folder paths from
17	//! `HKEY_USERS\{SID}\SOFTWARE\...` for each provider.  When a registry key is
18	//! absent the function falls back to `%USERPROFILE%`-based defaults so the
19	//! enforcer degrades gracefully on non-standard installations.
20	
21	use std::path::PathBuf;
22	
23	use dlp_common::{Classification, Decision};
24	
25	use crate::interception::FileAction;
26	
27	// ---------------------------------------------------------------------------
28	// Public types
29	// ---------------------------------------------------------------------------
30	
31	/// Identifies which cloud sync provider owns a sync folder.
32	#[derive(Debug, Clone, PartialEq, Eq)]
33	pub enum CloudProvider {
34	    /// Microsoft OneDrive (personal or business).
35	    OneDrive,
36	    /// Google Drive / Drive for Desktop.
37	    GoogleDrive,
38	    /// Dropbox.
39	    Dropbox,
40	    /// Box Drive.
41	    Box,
42	}
43	
44	impl CloudProvider {
45	    /// Returns the human-readable display name used in block-reason strings.
46	    fn display_name(&self) -> &'static str {
47	        match self {
48	            Self::OneDrive => "OneDrive",
49	            Self::GoogleDrive => "Google Drive",
50	            Self::Dropbox => "Dropbox",
51	            Self::Box => "Box",
52	        }
53	    }
54	}
55	
56	/// Indicates how a [`SyncPath`] was discovered.
57	#[derive(Debug, Clone, PartialEq, Eq)]
58	pub enum PathSource {
59	    /// Path was read directly from the Windows registry.
60	    Registry,
61	    /// Registry key was absent; a `%USERPROFILE%`-based default was used.
62	    Fallback,
63	}
64	
65	/// A resolved cloud-sync folder path for a specific provider.
66	#[derive(Debug, Clone, PartialEq, Eq)]
67	pub struct SyncPath {
68	    /// Which cloud provider owns this folder.
69	    pub provider: CloudProvider,
70	    /// Absolute path string with a trailing backslash.
71	    pub path: String,
72	    /// How the path was discovered.
73	    pub source: PathSource,
74	}
75	
76	// ---------------------------------------------------------------------------
77	// Registry-based path resolution
78	// ---------------------------------------------------------------------------
79	
80	/// Resolves the actual cloud sync folder paths for all four providers
81	/// from `HKEY_USERS\{user_sid}\SOFTWARE\...`.
82	///
83	/// # Arguments
84	///
85	/// * `user_sid` - The SID string of the logged-on user (e.g. `S-1-5-21-...`).
86	///   Pass an empty string to skip registry probing and return only fallbacks.
87	///
88	/// # Returns
89	///
90	/// A `Vec<SyncPath>` with one entry per discovered folder.  When a registry
91	/// key is absent the function pushes a fallback entry using `%USERPROFILE%`.
92	/// Failures to open a key are logged at WARN level; the function never panics.
93	pub fn resolve_sync_paths(user_sid: &str) -> Vec<SyncPath> {
94	    let mut paths: Vec<SyncPath> = Vec::with_capacity(8);
95	
96	    #[cfg(windows)]
97	    {
98	        if !user_sid.is_empty() {
99	            resolve_onedrive(user_sid, &mut paths);
100	            resolve_google_drive(user_sid, &mut paths);
101	            resolve_dropbox(user_sid, &mut paths);
102	            resolve_box(user_sid, &mut paths);
103	        }
104	    }
105	    #[cfg(not(windows))]
106	    let _ = user_sid; // suppress unused-variable warning on non-Windows
107	
108	    // Fill in any provider that did not get a registry hit.
109	    push_missing_fallbacks(&mut paths);
110	
111	    paths
112	}
113	
114	/// Ensures every provider has at least one fallback entry when registry
115	/// discovery did not produce a result for that provider.
116	fn push_missing_fallbacks(paths: &mut Vec<SyncPath>) {
117	    let userprofile =
118	        std::env::var("USERPROFILE").unwrap_or_else(|_| r"C:\Users\Default".to_string());
119	
120	    let providers: &[(&CloudProvider, &str)] = &[
121	        (&CloudProvider::OneDrive, "OneDrive"),
122	        (&CloudProvider::GoogleDrive, "Google Drive"),
123	        (&CloudProvider::Dropbox, "Dropbox"),
124	        (&CloudProvider::Box, "Box"),
125	    ];
126	
127	    for (provider, folder_name) in providers {
128	        let already_present = paths.iter().any(|sp| &sp.provider == *provider);
129	        if !already_present {
130	            let raw = format!(r"{}\{}", userprofile, folder_name);
131	            paths.push(SyncPath {
132	                provider: (*provider).clone(),
133	                path: normalize_path(&raw),
134	                source: PathSource::Fallback,
135	            });
136	        }
137	    }
138	}
139	
140	/// Normalises a raw path string: converts separators via `PathBuf` and appends
141	/// a trailing backslash so prefix checks work correctly.
142	fn normalize_path(raw: &str) -> String {
143	    let expanded = expand_env_vars(raw);
144	    let mut s = PathBuf::from(expanded.as_ref())
145	        .to_string_lossy()
146	        .into_owned();
147	    if !s.ends_with('\\') {
148	        s.push('\\');
149	    }
150	    s
151	}
152	
153	/// Expands a single leading `%VARNAME%` token if present.
154	///
155	/// Only handles the common case where `%USERPROFILE%` appears in registry
156	/// strings returned by cloud clients.  Full `ExpandEnvironmentStringsW` would
157	/// be ideal but adding it here avoids another unsafe block for a narrow case.
158	fn expand_env_vars(raw: &str) -> std::borrow::Cow<'_, str> {
159	    if let Some(after_pct) = raw.strip_prefix('%') {
160	        if let Some(end) = after_pct.find('%') {
161	            let var_name = &after_pct[..end];
162	            if let Ok(value) = std::env::var(var_name) {
163	                let rest = &after_pct[end + 1..];
164	                return std::borrow::Cow::Owned(format!("{}{}", value, rest));
165	            }
166	        }
167	    }
168	    std::borrow::Cow::Borrowed(raw)
169	}
