419	/// Probes Dropbox sync folder from `HKEY_USERS\{sid}\SOFTWARE\Dropbox\ks`.
420	#[cfg(windows)]
421	fn resolve_dropbox(sid: &str, out: &mut Vec<SyncPath>) {
422	    let dropbox_key = r"SOFTWARE\Dropbox\ks";
423	    if let Some(key) = open_user_key(sid, dropbox_key) {
424	        if let Some(raw) = read_reg_string(key.0, "dropbox_path") {
425	            if !raw.is_empty() {
426	                tracing::info!(
427	                    sid = %sid, path = %raw,
428	                    "cloud enforcer: Dropbox path resolved from registry"
429	                );
430	                out.push(SyncPath {
431	                    provider: CloudProvider::Dropbox,
432	                    path: normalize_path(&raw),
433	                    source: PathSource::Registry,
434	                });
435	            }
436	        }
437	    }
438	}
