440	/// Probes Box Drive folder path from `HKEY_USERS\{sid}\SOFTWARE\Box\Box`.
441	#[cfg(windows)]
442	fn resolve_box(sid: &str, out: &mut Vec<SyncPath>) {
443	    let box_key = r"SOFTWARE\Box\Box";
444	    if let Some(key) = open_user_key(sid, box_key) {
445	        if let Some(raw) = read_reg_string(key.0, "FolderPath") {
446	            if !raw.is_empty() {
447	                tracing::info!(
448	                    sid = %sid, path = %raw,
449	                    "cloud enforcer: Box path resolved from registry"
450	                );
451	                out.push(SyncPath {
452	                    provider: CloudProvider::Box,
453	                    path: normalize_path(&raw),
454	                    source: PathSource::Registry,
455	                });
456	            }
457	        }
458	    }
459	}
