461	// ---------------------------------------------------------------------------
462	// Active-session SID detection
463	// ---------------------------------------------------------------------------
464	
465	/// Returns the SID string of the user logged on at the active console session.
466	///
467	/// Uses `WTSGetActiveConsoleSessionId` + `WTSQuerySessionInformationW`
468	/// (username) + `LookupAccountNameW` to obtain a SID string.  Falls back to
469	/// scanning `HKEY_USERS` subkeys and returning the first non-system hive when
470	/// the WTS path fails (service running in Session 0 during boot, etc.).
471	///
472	/// Returns an empty `String` when no active user can be determined, which
473	/// causes [`resolve_sync_paths`] to skip registry probing and return only
474	/// fallbacks.
475	pub fn active_user_sid() -> String {
476	    #[cfg(windows)]
477	    {
478	        active_user_sid_windows()
479	    }
480	    #[cfg(not(windows))]
481	    {
482	        String::new()
483	    }
484	}
485	
486	#[cfg(windows)]
487	fn active_user_sid_windows() -> String {
488	    use windows::Win32::{
489	        Security::{Authorization::ConvertSidToStringSidW, LookupAccountNameW, PSID},
490	        System::RemoteDesktop::{
491	            WTSFreeMemory, WTSGetActiveConsoleSessionId, WTSQuerySessionInformationW, WTSUserName,
492	            WTS_CURRENT_SERVER_HANDLE,
493	        },
494	    };
495	
496	    // Step 1: get active console session ID.
497	    let session_id = unsafe { WTSGetActiveConsoleSessionId() };
498	
499	    // Step 2: get the username for that session.
500	    let mut buf_ptr = windows::core::PWSTR::null();
501	    let mut buf_len: u32 = 0;
502	    // WTSQuerySessionInformationW takes Option<HANDLE> for the server parameter.
503	    let ok = unsafe {
504	        WTSQuerySessionInformationW(
505	            Some(WTS_CURRENT_SERVER_HANDLE),
506	            session_id,
507	            WTSUserName,
508	            &mut buf_ptr,
509	            &mut buf_len,
510	        )
511	    };
512	    if ok.is_err() || buf_ptr.is_null() {
513	        tracing::warn!(
514	            "cloud enforcer: WTSQuerySessionInformationW failed — using HKEY_USERS scan fallback"
515	        );
516	        return scan_hkey_users_for_sid();
517	    }
518	
519	    // Convert the wide-char username (buf_len is in bytes, including null terminator).
520	    let char_count = (buf_len as usize / 2).saturating_sub(1);
521	    let username_wide: &[u16] =
522	        unsafe { std::slice::from_raw_parts(buf_ptr.as_ptr(), char_count) };
523	    let username = String::from_utf16_lossy(username_wide).to_string();
524	    unsafe { WTSFreeMemory(buf_ptr.as_ptr().cast()) };
525	
526	    if username.is_empty() {
527	        tracing::warn!(
528	            "cloud enforcer: empty username from WTS — using HKEY_USERS scan fallback"
529	        );
530	        return scan_hkey_users_for_sid();
531	    }
532	
533	    // Step 3: LookupAccountNameW to get PSID.
534	    let username_wide2: Vec<u16> = username.encode_utf16().chain(std::iter::once(0)).collect();
535	    let mut sid_buf = vec![0u8; 256];
536	    let mut sid_size = sid_buf.len() as u32;
537	    let mut domain_buf = vec![0u16; 256];
538	    let mut domain_size = domain_buf.len() as u32;
539	    let mut sid_name_use = windows::Win32::Security::SID_NAME_USE::default();
540	
541	    let lookup_ok = unsafe {
542	        LookupAccountNameW(
543	            PCWSTR::null(),
544	            PCWSTR::from_raw(username_wide2.as_ptr()),
545	            Some(PSID(sid_buf.as_mut_ptr().cast())),
546	            &mut sid_size,
547	            // referenceddomainname: Option<PWSTR>
548	            Some(windows::core::PWSTR::from_raw(domain_buf.as_mut_ptr())),
549	            &mut domain_size,
550	            &mut sid_name_use,
551	        )
552	    };
553	    if lookup_ok.is_err() {
554	        tracing::warn!(
555	            username = %username,
556	            "cloud enforcer: LookupAccountNameW failed — using HKEY_USERS scan fallback"
557	        );
558	        return scan_hkey_users_for_sid();
559	    }
560	
561	    // Step 4: ConvertSidToStringSidW → SID string.
562	    let psid = PSID(sid_buf.as_mut_ptr().cast());
563	    let mut sid_str_ptr = windows::core::PWSTR::null();
564	    let conv_ok = unsafe { ConvertSidToStringSidW(psid, &mut sid_str_ptr) };
565	    if conv_ok.is_err() || sid_str_ptr.is_null() {
566	        tracing::warn!("cloud enforcer: ConvertSidToStringSidW failed");
567	        return String::new();
568	    }
569	
570	    let sid_string = unsafe { sid_str_ptr.to_string().unwrap_or_default() };
571	    // ConvertSidToStringSidW allocates via LocalAlloc; free with LocalFree.
572	    unsafe {
573	        let _ = windows::Win32::Foundation::LocalFree(Some(windows::Win32::Foundation::HLOCAL(
574	            sid_str_ptr.as_ptr().cast(),
575	        )));
576	    }
577	    sid_string
578	}
579	
580	/// Fallback: scan `HKEY_USERS` subkeys and return the first entry that looks
581	/// like a real user SID (starts with `S-1-5-21-`, not `.DEFAULT` or `_Classes`).
582	#[cfg(windows)]
583	fn scan_hkey_users_for_sid() -> String {
584	    let subkeys = enum_subkeys(HKEY_USERS);
585	    for name in subkeys {
586	        if name.starts_with("S-1-5-21-") && !name.ends_with("_Classes") {
587	            tracing::info!(sid = %name, "cloud enforcer: resolved SID via HKEY_USERS scan");
588	            return name;
589	        }
590	    }
591	    tracing::warn!("cloud enforcer: no user SID found in HKEY_USERS");
592	    String::new()
593	}
