595	// ---------------------------------------------------------------------------
596	// CloudEnforcer
597	// ---------------------------------------------------------------------------
598	
599	/// Result returned by [`CloudEnforcer::check`] when a cloud sync operation is
600	/// blocked.
601	#[derive(Debug, Clone, PartialEq)]
602	pub struct CloudBlockResult {
603	    /// The enforcement decision — currently always `Decision::DENY`.
604	    pub decision: Decision,
605	    /// Human-readable reason for the block.
606	    pub reason: String,
607	    /// The detected sync provider display name (e.g., "OneDrive").
608	    pub provider: String,
609	    /// `true` if the UI should display a toast.
610	    pub notify: bool,
611	}
612	
613	/// Enforces DLP policies on file operations inside cloud sync folders.
614	///
615	/// Held behind `Arc` so it can be shared between the event loop and future
616	/// cloud notification handlers without cloning the underlying state.
617	pub struct CloudEnforcer {
618	    /// Resolved cloud sync folder paths with provider metadata.
619	    sync_paths: Vec<SyncPath>,
620	}
621	
622	impl Default for CloudEnforcer {
623	    fn default() -> Self {
624	        Self::new()
625	    }
626	}
