628	impl CloudEnforcer {
629	    /// Constructs a new [`CloudEnforcer`] by calling [`resolve_sync_paths`]
630	    /// with the active console user's SID.
631	    ///
632	    /// Falls back to `%USERPROFILE%`-based defaults when the active user
633	    /// cannot be determined or registry keys are absent.
634	    pub fn new() -> Self {
635	        let sid = active_user_sid();
636	        let sync_paths = resolve_sync_paths(&sid);
637	        tracing::info!(
638	            sid = %sid,
639	            path_count = sync_paths.len(),
640	            "cloud enforcer: sync paths resolved"
641	        );
642	        Self { sync_paths }
643	    }
644	
645	    /// Constructs a new [`CloudEnforcer`] with explicit sync folder prefixes.
646	    ///
647	    /// Each `String` is wrapped as a `SyncPath` with provider `OneDrive` and
648	    /// source `Fallback`.  This preserves backward compatibility with the
649	    /// existing test suite (TC-30..TC-33) which injects raw path strings.
650	    pub fn with_paths(paths: Vec<String>) -> Self {
651	        let sync_paths = paths
652	            .into_iter()
653	            .map(|p| {
654	                let path = normalize_path(&p);
655	                SyncPath {
656	                    provider: CloudProvider::OneDrive,
657	                    path,
658	                    source: PathSource::Fallback,
659	                }
660	            })
661	            .collect();
662	        Self { sync_paths }
663	    }
664	
665	    /// Constructs a [`CloudEnforcer`] with fully typed [`SyncPath`] entries.
666	    ///
667	    /// Used by unit tests that need to exercise provider-specific routing.
668	    pub fn with_sync_paths(sync_paths: Vec<SyncPath>) -> Self {
669	        Self { sync_paths }
670	    }
671	
672	    /// Evaluates whether the given file operation should be blocked based on
673	    /// cloud sync folder policies.
674	    ///
675	    /// Returns `Some(CloudBlockResult)` for T3/T4 write operations inside a
676	    /// sync folder. All other operations return `None` (fall through to ABAC).
677	    ///
678	    /// # Arguments
679	    ///
680	    /// * `path` - Full file path of the operation.
681	    /// * `action` - The [`FileAction`] being evaluated.
682	    ///
683	    /// # Returns
684	    ///
685	    /// - `Some(CloudBlockResult)` — T3/T4 file in sync folder; block.
686	    /// - `None` — not a sync path, or non-sensitive classification; proceed to ABAC.
687	    #[must_use]
688	    pub fn check(&self, path: &str, action: &FileAction) -> Option<CloudBlockResult> {
689	        if !is_write_like_action(action) {
690	            return None;
691	        }
692	
693	        let sync_path = self.detect_sync_provider(path)?;
694	        let provider_name = sync_path.provider.display_name().to_string();
695	
696	        // Placeholder classification for S02: real ABAC classification will
697	        // be wired in S03.
698	        let classification = provisional_sync_classification(path);
699	
700	        if classification.is_sensitive() {
701	            tracing::info!(
702	                path = %path,
703	                provider = %provider_name,
704	                classification = ?classification,
705	                decision = ?Decision::DENY,
706	                "cloud enforcer decision"
707	            );
708	            Some(CloudBlockResult {
709	                decision: Decision::DENY,
710	                reason: format!(
711	                    "Cloud sync blocked: {classification} file in {provider_name} folder"
712	                ),
713	                provider: provider_name,
714	                notify: true,
715	            })
716	        } else {
717	            tracing::info!(
718	                path = %path,
719	                provider = %provider_name,
720	                classification = ?classification,
721	                decision = ?Decision::ALLOW,
722	                "cloud enforcer decision"
723	            );
724	            None
725	        }
726	    }
727	
728	    /// Returns the [`SyncPath`] whose `path` prefix matches `path`, or `None`.
729	    fn detect_sync_provider(&self, path: &str) -> Option<&SyncPath> {
730	        let lower = path.to_lowercase();
731	        self.sync_paths
732	            .iter()
733	            .find(|sp| lower.starts_with(&sp.path.to_lowercase()))
734	    }
735	}
