740	
741	/// Returns `true` for actions that represent a file being written or created
742	/// in a way that could trigger a cloud upload.
743	fn is_write_like_action(action: &FileAction) -> bool {
744	    matches!(
745	        action,
746	        FileAction::Created { .. } | FileAction::Written { .. } | FileAction::Moved { .. }
747	    )
748	}
749	
750	/// Provisional path-based classification heuristic (S01/S02 placeholder).
751	///
752	/// - Paths containing "restricted" → T4
753	/// - Paths containing "confidential" → T3
754	/// - Everything else → T2
755	///
756	/// Phase S03 will integrate with the real ABAC classification engine.
757	fn provisional_sync_classification(path: &str) -> Classification {
758	    let lower = path.to_lowercase();
759	    if lower.contains(r"\restricted\") || lower.contains("restricted") {
760	        Classification::T4
761	    } else if lower.contains(r"\confidential\") || lower.contains("confidential") {
762	        Classification::T3
763	    } else {
764	        Classification::T2
765	    }
766	}
