49	/// Builds the classification string for a USB trust tier.
50	fn usb_classification(tier: UsbTrustTier) -> String {
51	    match tier {
52	        UsbTrustTier::Blocked => "USB-Blocked".to_string(),
53	        UsbTrustTier::ReadOnly => "USB-ReadOnly".to_string(),
54	        UsbTrustTier::FullAccess => {
55	            unreachable!("FullAccess never produces a block result")
56	        }
57	    }
58	}
