60	/// Builds the toast title and body for a USB block result.
61	fn usb_toast_message(usb_result: &crate::usb_enforcer::UsbBlockResult) -> (String, String) {
62	    match usb_result.tier {
63	        UsbTrustTier::Blocked => (
64	            "USB Device Blocked".to_string(),
65	            format!(
66	                "{} - this device is not permitted",
67	                usb_result.identity.description
68	            ),
69	        ),
70	        UsbTrustTier::ReadOnly => (
71	            "USB Device Read-Only".to_string(),
72	            format!(
73	                "{} - write operations are not permitted",
74	                usb_result.identity.description
75	            ),
76	        ),
77	        UsbTrustTier::FullAccess => {
78	            unreachable!("FullAccess never returns a block result from UsbEnforcer::check")
79	        }
80	    }
81	}
