83	/// Emits a USB block audit event and notifies the UI.
84	fn handle_usb_block(
85	    ctx: &EmitContext,
86	    user_sid: &str,
87	    user_name: &str,
88	    path: &str,
89	    pid: u32,
90	    usb_result: &crate::usb_enforcer::UsbBlockResult,
91	) {
92	    let mut audit_event = AuditEvent::new(
93	        EventType::Block,
94	        user_sid.to_string(),
95	        user_name.to_string(),
96	        path.to_string(),
97	        // Classification not yet resolved at this point; T1 is the
98	        // conservative public-tier placeholder (not used for ABAC here).
99	        dlp_common::Classification::T1,
100	        // Action placeholder — USB check fires before action mapping.
101	        dlp_common::Action::WRITE,
102	        usb_result.decision,
103	        ctx.agent_id.clone(),
104	        ctx.session_id,
105	    )
106	    .with_access_context(AuditAccessContext::Local)
107	    .with_device_identity(Some(usb_result.identity.clone()))
108	    .with_owner(usb_result.owner_sid.clone(), usb_result.owner_user.clone());
109	    // WR-03: no policy matched this enforcement — leave policy_id as None
110	    // so SIEM rules that test `policy_id IS NOT NULL` are not misled.
111	    // Set only policy_name to convey the enforcement reason.
112	    audit_event.policy_name = Some("USB enforcement: device blocked or read-only".to_string());
113	
114	    // AUDIT-04 (Phase 42): Enrich with app identity from the initiating process.
115	    crate::audit_emitter::enrich_audit_with_app_identity(&mut audit_event, pid);
116	    crate::audit_emitter::set_destination_application(&mut audit_event, None);
117	
118	    emit_audit(ctx, &mut audit_event);
119	
120	    if usb_result.decision.is_denied() {
121	        let msg = Pipe1AgentMsg::BlockNotify {
122	            reason: "USB enforcement: device blocked or read-only".to_string(),
123	            classification: usb_classification(usb_result.tier),
124	            resource_path: path.to_string(),
125	            policy_id: String::new(),
126	        };
127	        if let Err(e) = pipe1::send_to_ui(ctx.session_id, &msg) {
128	            warn!(
129	                error = %e,
130	                session_id = ctx.session_id,
131	                "failed to send USB BlockNotify to UI"
132	            );
133	        }
134	    }
135	
136	    // USB-04: toast notification — fires only when per-drive cooldown has not suppressed it.
137	    if usb_result.notify {
138	        let (title, body) = usb_toast_message(usb_result);
139	        crate::ipc::pipe2::BROADCASTER.broadcast(&Pipe2AgentMsg::Toast { title, body });
140	    }
141	}
