274	/// Runs the file interception event loop.
275	///
276	/// This is the core audit pipeline integration point.  It receives [`FileAction`]
277	/// events from the file monitor via `rx`, evaluates each one, emits an audit
278	/// event, and — for blocking decisions — notifies the UI via Pipe 1.
279	///
280	/// Intended to run inside `tokio::spawn`.  Exits when `rx` is closed or an
281	/// unrecoverable error occurs.
282	///
283	/// # Arguments
284	///
285	/// * `rx` — channel receiving [`FileAction`] events from the file monitor
286	/// * `offline` — the shared offline manager (engine client + cache)
287	/// * `ctx` — shared audit context (agent_id, session)
288	/// * `session_map` — per-session identity map for resolving file owners
289	/// * `ad_client` — optional AD client for group/trust/location resolution (None = fallback to placeholder)
290	/// * `usb_enforcer` — optional USB trust-tier enforcer; fires before ABAC evaluation (None = USB enforcement disabled)
291	/// * `cloud_enforcer` — optional cloud sync enforcer; fires after disk, before ABAC (None = cloud enforcement disabled)
292	pub async fn run_event_loop(
293	    mut rx: mpsc::Receiver<FileAction>,
294	    offline: Arc<OfflineManager>,
295	    ctx: EmitContext,
296	    session_map: Arc<SessionIdentityMap>,
297	    ad_client: Arc<Option<dlp_common::AdClient>>,
298	    usb_enforcer: Option<Arc<UsbEnforcer>>,
299	    disk_enforcer: Option<Arc<DiskEnforcer>>,
300	    cloud_enforcer: Option<Arc<CloudEnforcer>>,
301	) {
302	    info!("interception event loop started");
303	
304	    while let Some(action) = rx.recv().await {
305	        let action = action.clone();
306	        let path = action.path().to_string();
307	        let pid = action.process_id();
308	
309	        // ── Resolve identity ───────────────────────────────────────────────
310	        // Resolved early so that both the USB short-circuit path and the ABAC
311	        // path emit accurate user attribution in their audit events.
312	        let (user_sid, user_name) = {
313	            let (app_path, _app_hash) = audit_emitter::get_application_metadata(pid);
314	            debug!(pid, path = %path, ?app_path, "file action received");
315	            // Resolve the actual user from the file path using the
316	            // per-session identity map (path heuristic + single-user
317	            // fallback).
318	            session_map.resolve_for_path(&path)
319	        };
320	
321	        // ── USB enforcement (pre-ABAC check) ─────────────────────────────
322	        // Fires before the ABAC engine. Blocked or ReadOnly+write operations
323	        // short-circuit here and emit an audit Block event (D-11).
324	        if let Some(ref enforcer) = usb_enforcer {
325	            if let Some(usb_result) = enforcer.check(&path, &action) {
326	                handle_usb_block(&ctx, &user_sid, &user_name, &path, pid, &usb_result);
327	                continue; // skip ABAC evaluation for this event
328	            }
329	        }
330	
331	        // ── Disk enforcement (pre-ABAC check) ────────────────────────────
332	        // Fires after USB enforcement, before the ABAC engine. Blocks writes
333	        // to unregistered fixed disks (DISK-04, D-06, D-07). Uses `continue`
334	        // to skip ABAC evaluation when blocked, mirroring the USB pattern.
335	        if let Some(ref enforcer) = disk_enforcer {
336	            if let Some(disk_result) = enforcer.check(&path, &action) {
337	                handle_disk_block(&ctx, &user_sid, &user_name, &path, pid, &disk_result);
338	                continue; // skip ABAC evaluation for this event
339	            }
340	        }
341	
342	        // ── Cloud enforcement (pre-ABAC check) ───────────────────────────
343	        // Fires after disk enforcement, before the ABAC engine. Blocks T3/T4
344	        // writes to known cloud sync folders (M017/S01).
345	        if let Some(ref enforcer) = cloud_enforcer {
346	            if let Some(cloud_result) = enforcer.check(&path, &action) {
347	                handle_cloud_block(&ctx, &user_sid, &user_name, &path, pid, &cloud_result);
348	                continue; // skip ABAC evaluation for this event
349	            }
350	        }
351	
352	        let abac_action = PolicyMapper::action_for(&action);
353	
354	        // ── Provisional classification (offline mode / extension layer) ───
355	        // provisional_classification always returns >= T1, so no max() needed.
356	        let classification = PolicyMapper::provisional_classification(&path);
357	
358	        // ── Build evaluation request ──────────────────────────────────────
359	        let subject = if let Some(ref client) = *ad_client {
360	            let vpn_subnets = client.vpn_subnets_str();
361	            let identity = WindowsIdentity {
362	                sid: user_sid.clone(),
363	                username: user_name.clone(),
364	                primary_group: None,
365	            };
366	            identity.to_subject_with_ad(client, &vpn_subnets).await
367	        } else {
368	            // Fallback: placeholder values (no AD configured).
369	            Subject {
370	                user_sid: user_sid.clone(),
371	                user_name: user_name.clone(),
372	                groups: Vec::new(),
373	                device_trust: dlp_common::DeviceTrust::Unknown,
374	                network_location: dlp_common::NetworkLocation::Unknown,
375	            }
376	        };
377	
378	        let request = EvaluateRequest {
379	            subject,
380	            resource: Resource {
381	                path: path.clone(),
382	                classification,
383	            },
384	            environment: Environment {
385	                timestamp: chrono::Utc::now(),
386	                session_id: ctx.session_id,
387	                access_context: AccessContext::Local,
388	            },
389	            action: abac_action,
390	            agent: ctx.machine_name.as_ref().map(|machine_name| AgentInfo {
391	                machine_name: Some(machine_name.clone()),
392	                current_user: Some(user_name.clone()),
393	            }),
394	            ..Default::default()
395	        };
396	
397	        // ── Evaluate against Policy Engine ────────────────────────────────
398	        let response = offline.evaluate(&request).await;
399	
400	        // ── Determine event type and decision ─────────────────────────────
401	        let response_reason = response.reason.clone();
402	        let response_policy_id = response.matched_policy_id.clone();
403	        let decision = response.decision;
404	
405	        let event_type = match decision {
406	            Decision::ALLOW | Decision::AllowWithLog => EventType::Access,
407	            Decision::DENY => EventType::Block,
408	            Decision::DenyWithAlert => EventType::Alert,
409	        };
410	
411	        let is_denied = decision.is_denied();
412	
413	        // ── Emit audit event ───────────────────────────────────────────────
414	        let policy_id_str = response_policy_id.unwrap_or_default();
415	        let mut audit_event = AuditEvent::new(
416	            event_type,
417	            user_sid.clone(),
418	            user_name.clone(),
419	            path.clone(),
420	            classification,
421	            abac_action,
422	            decision,
423	            ctx.agent_id.clone(),
424	            ctx.session_id,
425	        )
426	        .with_access_context(AuditAccessContext::Local)
427	        .with_policy(policy_id_str.clone(), response_reason.clone());
428	
429	        // AUDIT-04 (Phase 42): Enrich with app identity from the initiating process.
430	        crate::audit_emitter::enrich_audit_with_app_identity(&mut audit_event, pid);
431	        crate::audit_emitter::set_destination_application(&mut audit_event, None);
432	
433	        emit_audit(&ctx, &mut audit_event);
434	
435	        // ── UI notification for blocking decisions ──────────────────────────
436	        if is_denied {
437	            if let Err(e) = pipe1::send_to_ui(
438	                ctx.session_id,
439	                &Pipe1AgentMsg::BlockNotify {
440	                    reason: response_reason,
441	                    classification: classification.to_string(),
442	                    resource_path: path,
443	                    policy_id: policy_id_str,
444	                },
445	            ) {
446	                warn!(error = %e, session_id = ctx.session_id, "failed to send BlockNotify to UI");
447	            }
448	        }
449	    }
450	
451	    info!("interception event loop exited");
452	}
